// Pack n runs (4 bits each) into one key; runs must be 1..15.
constexpr std::uint32_t pack_runs(const int* runs, int n) {
    std::uint32_t v = 0;
    for (int i = 0; i < n; ++i)
        v |= (static_cast<std::uint32_t>(runs[i]) & 0xFu) << (4 * i);
    return v;
}

constexpr int unpack_run(std::uint32_t packed, int i) {
    return static_cast<int>((packed >> (4 * i)) & 0xFu);
}

